<?php
/** Exporta dataset v6: una fila = estudiante + curso + bimestre base cerrado. */
if(PHP_SAPI!=='cli'){fwrite(STDERR,"Solo CLI.\n");exit(1);}
require_once __DIR__.'/../edusync/db_connect.php';
require_once __DIR__.'/../edusync/includes/predictive_course_risk.php';

$options=getopt('',['school:','year::','output::']);$schoolId=(int)($options['school']??0);$yearFilter=isset($options['year'])&&$options['year']!==false&&$options['year']!==''?(int)$options['year']:null;$output=(string)($options['output']??(__DIR__.'/../storage/course_risk_dataset.csv'));
if($schoolId<=0){fwrite(STDERR,"Falta --school=<ID_REAL>.\n");exit(1);}if(!isset($conn)||!($conn instanceof mysqli)){fwrite(STDERR,"Sin conexión MySQL.\n");exit(1);}

function course_export_years(mysqli $conn,int $schoolId,?int $yearId): array{$sql='SELECT id,year,start_date,end_date,is_active FROM academic_year WHERE school_id=?'.($yearId?' AND id=?':'').' ORDER BY start_date,id';$stmt=$conn->prepare($sql);if(!$stmt)return[];if($yearId)$stmt->bind_param('ii',$schoolId,$yearId);else$stmt->bind_param('i',$schoolId);$stmt->execute();$res=$stmt->get_result();$rows=[];while($r=$res->fetch_assoc())$rows[]=$r;$stmt->close();return$rows;}
function course_export_students(mysqli $conn,int $schoolId,int $yearId,int $bimester): array{$where=['s.school_id=?','CAST(e.bimestre AS UNSIGNED)=?'];$types='ii';$params=[$schoolId,$bimester];if(edu_predictive_column_exists($conn,'teacher_courses','academic_year_id')){$where[]='tc.academic_year_id=?';$types.='i';$params[]=$yearId;}if(edu_predictive_column_exists($conn,'evaluations','academic_year_id')){$where[]='e.academic_year_id=?';$types.='i';$params[]=$yearId;}if(edu_predictive_column_exists($conn,'evaluations','status'))$where[]="COALESCE(e.status,'Activa')<>'Anulada'";$sql='SELECT DISTINCT s.id,s.name,s.nivel,s.grado,s.seccion FROM evaluation_grades eg INNER JOIN student s ON s.id=eg.student_id INNER JOIN evaluations e ON e.id=eg.evaluation_id INNER JOIN teacher_courses tc ON tc.id=e.teacher_course_id WHERE '.implode(' AND ',$where).' ORDER BY s.id';$stmt=$conn->prepare($sql);if(!$stmt)return[];edu_predictive_bind($stmt,$types,$params);$stmt->execute();$res=$stmt->get_result();$rows=[];while($r=$res->fetch_assoc())$rows[]=$r;$stmt->close();return$rows;}
function course_export_val($v){return$v===null||$v===''?'':round((float)$v,6);}

$features=['course_mean_current','distance_to_critical','course_trend','previous_course_available','same_year_course_slope','same_year_periods_available','low_grade_rate_current','missing_grade_rate_current','evaluations_count_current','attendance_rate_30d','attendance_trend_same_year','late_30d','absent_30d','class_course_mean_current','class_low_grade_rate_current','class_students_critical_rate','student_vs_class_mean'];
$headers=array_merge(['school_id','academic_year_id','academic_year','student_id','nivel','grado','seccion','course_id','course_name','bimester','target_bimester','cutoff_date'], $features, ['graded_cells','expected_cells','missing_eval_absence_overlap','evaluation_date_available','target_course_critical']);
$dir=dirname($output);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir)){fwrite(STDERR,"No pude crear $dir.\n");exit(1);}$fh=fopen($output,'wb');if(!$fh){fwrite(STDERR,"No pude crear $output.\n");exit(1);}fputcsv($fh,$headers);

$rows=0;$positive=0;$negative=0;$pairs=[];$courses=[];$missingAttendance=0;$missingGrades=0;$dateOverlapAvailable=0;$skippedTarget=0;
foreach(course_export_years($conn,$schoolId,$yearFilter) as $year){$yearId=(int)$year['id'];foreach([1,2,3] as $b){$base=edu_predictive_bimester_closure($conn,$schoolId,$yearId,$b);$targetClosure=edu_predictive_bimester_closure($conn,$schoolId,$yearId,$b+1);if(empty($base['closed'])||empty($base['date'])||empty($targetClosure['closed']))continue;foreach(course_export_students($conn,$schoolId,$yearId,$b) as $student){$sid=(int)$student['id'];foreach(edu_course_risk_contexts_from_grades($conn,$sid,$schoolId,$yearId,$b) as $ctx){$target=edu_course_risk_target_next($conn,$sid,$schoolId,$yearId,$b,(int)$ctx['course_id']);if($target===null){$skippedTarget++;continue;}$f=edu_course_risk_feature_vector($conn,$sid,$schoolId,$yearId,$b,$ctx,(string)$base['date'],30);if($f['course_mean_current']===null)continue;$line=[$schoolId,$yearId,(string)($year['year']??$yearId),$sid,(string)$student['nivel'],(string)$student['grado'],(string)$student['seccion'],(int)$ctx['course_id'],(string)$ctx['course_name'],$b,$b+1,(string)$base['date']];foreach($features as $feature)$line[]=course_export_val($f[$feature]??null);$line[]=(int)$f['graded_cells'];$line[]=(int)$f['expected_cells'];$line[]=course_export_val($f['missing_eval_absence_overlap']??null);$line[]=!empty($f['evaluation_date_available'])?1:0;$line[]=$target;fputcsv($fh,$line);$rows++;if($target)$positive++;else$negative++;$pair=$b.'->'.($b+1);$pairs[$pair]=($pairs[$pair]??0)+1;$name=(string)$ctx['course_name'];$courses[$name]=($courses[$name]??0)+1;if((int)($f['attendance_records_30d']??0)===0)$missingAttendance++;if((int)($f['missing_grade_cells']??0)>0)$missingGrades++;if(!empty($f['evaluation_date_available']))$dateOverlapAvailable++;}}}}
fclose($fh);arsort($courses);
echo "Dataset por curso creado: $output\n";echo "Esquema: v6 estudiante + curso + bimestre\n";echo "Filas curso-periodo: $rows | positivas: $positive | negativas: $negative".($rows?' | prevalencia: '.number_format($positive/$rows*100,1).'%':'')."\n";echo "Estudiantes distintos: ";$ids=[];$rf=fopen($output,'rb');$h=fgetcsv($rf);$idx=array_flip($h);while(($r=fgetcsv($rf))!==false)$ids[$r[$idx['student_id']]]=true;fclose($rf);echo count($ids)."\n";echo "Pares: ".json_encode($pairs,JSON_UNESCAPED_UNICODE)."\n";echo "Cursos con más filas: ".json_encode(array_slice($courses,0,10,true),JSON_UNESCAPED_UNICODE)."\n";echo "Filas con alguna calificación faltante: $missingGrades\n";echo "Filas sin asistencia en ventana de 30 días: $missingAttendance\n";echo "Filas donde existe fecha académica de evaluación para cruce con asistencia: $dateOverlapAvailable\n";echo "Filas omitidas porque el mismo curso no tiene resultado observable en N+1: $skippedTarget\n";echo "IMPORTANTE: una nota faltante no se convirtió en cero. Teacher ID no se exporta como predictor.\n";
if($rows<300)echo "ADVERTENCIA: dataset por curso pequeño; interpretar validación con cautela.\n";
